values
  ('LM298AP1', 'AP1', 'AP', 1, 'Travesías y Tropiezos de Aldoquino Portomoro (vol . 1)', 'Jae Tanaka', 'Suplemento', (select id from public.categories where slug = 'otros'), '80', 'rústica color con solapas', 'A5 color', 20.00, '2026-07-31', '9125111371250', 'LM298AP1', 'ALMEAP1', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "EAN-13 válido por checksum, pero no tiene prefijo ISBN 978/979", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM298AP1", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM298AP1", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
  ('LM201B1', 'B1', 'B', 1, 'La Cripta Nefanda de Uztum el Maldito', 'Pedro Gil', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '32', 'grapado-color', 'b/n - A4', 5.00, '2017-01-25', 'LM201B1', 'LM201B1', 'ALMEB1', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM201B1", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 3, 4, 6, 1, array['Dungeon', 'Oneshot']::text[], 'Reúne a tu grupo de compañeros aventureros y atrévete a buscar la mítica cripta de Uztum, allende las Colinas Rojas, más allá de Reino Bosque y la Marca del Este, para descubrir sus secretos y maravillas de antaño. ¿Podrás sobrevevivir para ver otro día?', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b1-la-cripta-nefanda-de-uztum-el-maldito.md'),
  ('LM202B2', 'B2', 'B', 2, 'La Isla Misteriosa', 'Pedro Gil', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '32', 'grapado-color', 'b/n - A4', 5.00, '2017-01-25', 'LM202B2', 'LM202B2', 'ALMEB2', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM202B2", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 4, 6, 4, 6, 1, array['Exploración', 'Isla', 'Sandbox']::text[], 'Aventura para niveles 4-6 donde los aventureros deberán explorar una misteriosa isla llena de peligros.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b2-la-isla-misteriosa.md'),
  ('LM203B3', 'B3', 'B', 3, 'El Orbe de Amonhotep', 'Carlos Piedra Tutor', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '32', 'grapado-color', 'b/n - A4', 5.00, '2017-01-25', 'LM203B3', 'LM203B3', 'ALMEB3', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM203B3", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 5, 6, 4, 6, 2, array['Dungeon', 'Investigación', 'Reglamento', 'Urbano']::text[], 'Una aventura para personajes de nivel 5-6 ambientada en la mítica región de Neferu, en Cirinea, donde nuestros aventureros deberán encontrar y explorar una mítica mastaba en busca del Orbe de Amonhotep.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b3-el-orbe-de-amonhotep.md'),
  ('LM207B4', 'B4', 'B', 4, 'Muerte en la Mansión del Mago Malifax', 'Carlos de la Cruz', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '28', 'grapado', 'b/n A4', 6.00, '2018-03-23', 'LM207B4', 'LM207B4', 'ALMEB4', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM207B4", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 8, 9, 6, 8, 1, array['Exploración', 'Exterior', 'Torreón']::text[], 'El mago Malifax ha muerto. Nadie ha visto su cuerpo, pero en mitad de la noche la Campana Negra sonó trece veces, cada tañido más fuerte que el anterior. Después de la decimotercera campanada, la Torre Sin Puertas Ni Ventanas, en cuya cúspide estaba el artefacto, tembló y se derrumbó. Los que se atrevieron a acercarse al lugar juran que las runas de la Campana Negra, que refulgían con el fuego del infierno, se apagaron poco a poco. Inmediatamente el rumor se extendió como una plaga malsana por Marvalar: ¡Malifax había muerto! Y por tanto, los tesoros de su mansión estaban al alcance de aquellos lo suficientemente locos y atrevidos como para ir a buscarlos.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/B4-muerte-en-la-mansion-del-mago-malifax.md'),
  ('LM208B5', 'B5', 'B', 5, 'Incursión a la Tierra del Dios Azul', 'José Carlos «Kha» Domínguez', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '28', 'grapado', 'b/n A4', 6.00, '2018-03-23', 'LM208B5', 'LM208B5', 'ALMEB5', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM208B5", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 4, 5, 4, 5, 3, array['Ciencia Fantasía', 'Exploración', 'Investigación', 'Reglamento']::text[], 'Una estrella ha caído en el corazón de las estepas de las Tierras Nómadas y de ella ha empezado a extenderse una extraña jungla de hojas azules. Los animales mutan en sus cercanías, el cielo nocturno se llena de portentos y la gente tiene sueños y profecías nefandas.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b5-incursion-a-la-tierra-del-dios-azul.md'),
  ('LM212B6', 'B6', 'B', 6, 'Tiempo fuera del tiempo', 'Héctor Prieta de la Calle', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '20', 'rústica-color', 'b/n A4', 6.00, '2018-11-23', '.', 'LM212B6', 'ALMEB6', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM212B6", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 2, 4, 3, 5, 2, array['Fortaleza', 'Investigación']::text[], 'La vieja fortaleza de Dorman, perdida en las remotas vaguadas oscuras, más allá de las encrucijadas olvidadas, descansa imperturbable sumida en una maldición tan antigua como el tiempo, que pareciera haberse detenido entre las rocas negras y la hiedra seca de sus antaño orgullosas murallas. Quién sabe qué ignotos misterios y horrores aguardan en su interior.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b6-tiempo-fuera-del-tiempo.md'),
  ('LM214B7', 'B7', 'B', 7, 'Presentes Sangrientos', 'Alejandra González', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '20', 'rústica-color', 'b/n A4', 6.00, '2019-02-08', '.', 'LM214B7', 'ALMEB7', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM214B7", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 2, 4, 4, 5, 2, array['Exterior', 'Templo', 'Urbano']::text[], 'Desde las altas tierras al norte de la Marca del Este hasta la lejana Nirmala y más allá un antiguo mal extiende sus hebras oscuras y pocos conocen su existencia. Sus acólitos buscan algo que bien podría estar en manos de nuestros aventureros. ¿Podrán los mismos encontrarlo a tiempo y malograr sus planes antes de que sea tarde?', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b7-presentes-sangrientos.md'),
  ('LM215B8', 'B8', 'B', 8, 'La Tumba de Hielo', 'José Manue Palacios', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '16', 'rústica-color', 'b/n A4', 7.00, '2019-10-25', '.', 'LM215B8', 'ALMEB8', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM215B8", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 5, 1, 5, 2, array['Dragón', 'Fortaleza', 'Oneshot']::text[], 'Hace ahora seis años, el bastión enano de Martormenta sufrió un aciago destino cuando Dagobaris, un astuto dragón blanco, consiguió asaltar por la fuerza los salones y expulsar a los enanos del mismo. Los supervivientes fundaron el Campamento de los Desposeídos al pie del sendero que asciende hasta Martormenta, donde el jovencísimo Naen, el último de los Keroun, reúne fuerzas para acabar con el dragón y recuperar el legado de su familia.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b8-la-tumba-de-hielo.md'),
  ('LM216B9', 'B9', 'B', 9, 'La Última Frontera', 'Jorge Moreno', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '24', 'rústica-color', 'b/n A4', 7.00, '2019-10-25', '.', 'LM216B9', 'ALMEB9', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM216B9", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 2, 4, 5, 5, 1, array['Dragón', 'Exterior', 'Fortaleza']::text[], 'Contratados como escoltas de caravana, los aventureros deberán partir hacia el Fuerte del Oxus.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/B9-La%20%C3%BAltima%20frontera.md'),
  ('LM230B10', 'B10', 'B', 10, 'El Túmulo Perdido de Azgoz el Testarudo', 'vv.aa.', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '16', 'grapado color', 'A4 b/n', 7.50, '2021-03-18', '.', 'LM230B10', 'ALMEB10', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM230B10", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 3, 4, 6, 1, array['Dungeon']::text[], 'Azgoz fue un valiente caballero paladín. Murió y fue enterrado en un túmulo cerca de la ciudad, en las Colinas Azules. El paradero de su tumba se perdió.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b10-el-tumulo-perdido-de-azgoz-el-testarudo.md'),
  ('LM231B11', 'B11', 'B', 11, 'Las Cuevas del Clan Atronador', 'Manuel Pietro Serrano', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '20', 'grapado color', 'A4 b/n', 7.50, '2021-04-30', '9787702211620', 'LM231B11', 'ALMEB11', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM231B11", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 2, 4, 5, 2, array['Dungeon', 'Iniciación']::text[], 'Esta es una aventura introductoria, perfecta para iniciar a jovenes jugadores y niños, con un formato clasico y sencillo emula las antiguas aventuras de antaño.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b11-las-cuevas-del-clan-atronador.md'),
  ('LM235B12', 'B12', 'B', 12, 'El Monasterio del Dragón Dormido', 'Jose Francisco Asensi Noguera', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '12', 'grapado color', 'A4 b/n', 7.50, '2021-09-10', '9780201111620', 'LM235B12', 'ALMEB12', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM235B12", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 2, 4, 6, 1, array['Dragón', 'Exploración', 'Iniciación', 'Templo']::text[], 'Corren rumores en el pueblo sobre el viejo monasterio sobre la colina. No son pocos los que afirman que una enorme sierpe roja despertó de su letargo milenario para atacar las vetustas piedras antaño con su letal y poderosa arma de aliento flamígero. Algunos otros aseguran que el Dragón Rojo aún descansa en el oscuro interior de los ruinosos restos el enclave. Quizás todo ello no sean más que habladurías, pero la Marca precisa de valientes aventureros que arrojen luz sobre la historia.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b12-el-monasterio-del-dragon-dormido.md'),
  ('LM238B13', 'B13', 'B', 13, 'Sangre en la Nieve', 'Joaquín Blanes Garrido', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '20', 'grapado color', 'A4 b/n', 7.50, '2022-06-10', '9780201379228', 'LM238B13', 'ALMEB13', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM238B13", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 2, 2, 4, 6, 2, array['Exploración', 'Exterior', 'Investigación']::text[], 'Esta aventura está diseñada para un grupo de 4 a 6 personajes de niveles iniciales. Permite al Narrador situar a los PJs en un lugar inhóspito y salvaje lejos de la civilización, ahíto de peligros y desafíos.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b13-sangre-en-la-nieve.md'),
  ('LM239B14', 'B14', 'B', 14, 'Vileza en el Bastión de los Bandidos', 'Hugo Gil', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '32', 'grapado color', 'A4 b/n', 8.00, '2022-06-10', '9788436836233', 'LM239B14', 'ALMEB14', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM239B14", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 2, 4, 3, 6, 2, array['Dungeon', 'Fortaleza']::text[], 'Esta aventura esta planteada por el autor, como un “plug and play” para que, el Narrador, la utilice a su gusto dentro de su campaña o bien de forma totalmente independiente.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b14-vileza-en-el%20bastion-de-los-bandidos.md'),
  ('LM248B15', 'B15', 'B', 15, 'Las Minas del Elefante', 'José Carlos Domínguez..', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '24', 'grapado color', 'A4 b/n', 8.00, '2023-09-22', '9780195014761', 'LM248B15', 'ALMEB15', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM248B15", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 6, 7, 3, 5, 6, array['Dungeon', 'Exploración', 'Exterior', 'Templo']::text[], 'Los aventureros han oído hablar de las antiguas Minas del Elefante, llenas a rebosar de esmeraldas, y han descubierto que cierto comerciante de Kalanga ha obtenido un mapa hasta Umba-koi, donde están las minas, después de que un blanco borracho se lo diera a cambio de un último trago. El mercader no termina de creer en su autenticidad, pero está dispuesto a venderlo al mejor postor.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b15-las-minas-del-elefante.md'),
  ('LM249B16', 'B16', 'B', 16, 'La Pirámide del Faraón Negro', 'José Carlos Domínguez..', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '24', 'grapado color', 'A4 b/n', 8.00, '2023-09-22', '9780330291910', 'LM249B16', 'ALMEB16', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM249B16", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 4, 5, 3, 5, 2, array['Dungeon', 'Reglamento', 'Templo']::text[], 'Esta aventura está centrada en Neferu, la tierra de los faraones en Cirinea, donde los aventureros podrán saquear una antigua pirámide olvidada y las cámaras que se ocultan bajo ella.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b16-la-piramide-del-faraon-negro.md'),
  ('LM247B17', 'B17', 'B', 17, 'El Búcaro de Alabastro', 'Miguel Ángel Muñoz', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '28', 'grapado color', 'A4 b/n', 8.00, '2023-06-16', '9780202739953', 'LM247B17', 'ALMEB17', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM247B17", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 3, 4, 4, 6, 3, array['Dungeon', 'Exploración', 'Templo']::text[], 'Aventura que comienza en Urusal-din, la capital del califato de Visirtán, y llevará a los aventureros a una aldea perdida en el desierto de Eretria que esconde no pocos secretos.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/b17-el-bucaro-de-alabastro.md'),
