  ('LM293B42', 'B42', 'B', 42, 'El Lazareto de Robleda', 'Pedro J. González', 'Suplemento', (select id from public.categories where slug = 'aventuras-b'), '20', 'grapado color', 'A4 b/n', 10.00, '2026-05-29', '9660266375529', 'LM293B42', 'ALMEB42', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "EAN-13 válido por checksum, pero no tiene prefijo ISBN 978/979", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM293B42", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM293B42", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
  ('LM224BS1', 'BS1', 'BS', 1, 'Bestiario de Criaturas Extraordinarias', 'vv. aa.', 'Suplemento', (select id from public.categories where slug = 'bestiarios'), '28', 'grapado color', 'A4 b/n', 5.00, '2020-11-09', '9789201009623', 'LM224BS1', 'ALMEBS1', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM224BS1", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, array['Reglamento']::text[], 'Ampliación de nuevos monstruos y criaturas para incorporar a tus partidas, así como nuevas clases de personajes.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/BS1-bestiario.md'),
  ('LM204C1', 'C1', 'C', 1, 'Los Salones Anegados de Leviatan', 'Luis F. «Tadevs»', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '32', 'grapado-color', 'b/n - A4', 5.00, '2017-01-25', 'LM204C1', 'LM204C1', 'ALMEC1', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM204C1", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 5, 7, 3, 6, 3, array['Competición', 'Dungeon', 'Marítima']::text[], 'En los más profundo del oscuro y tempestuoso océano, aguardan los míticos Salones Anegados de Leviatán, ahítos de monstruos terribles, reliquias de otrora y riquezas más allá de lo imaginado.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/c1-los-salones-anegados.md'),
  ('LM209C2', 'C2', 'C', 2, 'La Catacumba de los Espantos de Kavaduz', 'Pedro Gil', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '40', 'grapado', 'b/n A4', 6.00, '2018-03-23', 'LM209C2', 'LM209C2', 'ALMEC2', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM209C2", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 12, 15, 4, 6, 2, array['Ciencia Fantasía', 'Competición', 'Dungeon']::text[], 'Escondida en las peligrosas vaguadas de las montañas de Cerrognoll, aguarda la llegada de intrépidos aventureros la vieja abadía de Kavadůz. Pues un gran mal ha anidado en su interior, en la más profunda oscuridad, amenazando con desencadenar un terrible mal sobre todo Valion.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/c2-la-catacumba-de-los-espantos-de-kavaduz.md'),
  ('LM218C3', 'C3', 'C', 3, 'El Jardín Negro', 'José Manue Palacios', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '24', 'rústica-color', 'b/n A4', 7.00, '2019-10-25', '.', 'LM218C3', 'ALMEC3', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM218C3", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 6, 10, 1, 5, 2, array['Competición', 'Exploración', 'Exterior', 'Torreón']::text[], 'Hace poco, una extraña floresta surgió al norte de la ciudad de Calamain, un amplio y oscuro laberinto de enredaderas, setos y espinos alrededor de una antigua almenara. De este Jardín Negro brotan todo tipo de monstruos que amenazan a los habitantes de la región. Las autoridades, desesperadas ya, buscan un grupo de aventureros corajudos dispuestos a arrostrar esta preternatural maldición.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/c3-el-jardin-negro.md'),
  ('LM236C4', 'C4', 'C', 4, 'La Cúpula de Huesos de Ixambel', 'Nacho Vega Matilla', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '28', 'grapado color', 'A4 b/n', 7.50, '2022-04-01', '9780201379625', 'LM236C4', 'ALMEC4', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Tiene prefijo ISBN 978/979, pero el checksum EAN-13 no es válido", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM236C4", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 8, 11, 4, 6, 2, array['Competición', 'Dungeon', 'Exploración']::text[], 'Las viejas sagas ungolitas, vetustas como el mismo tiempo, hablan de una terrible batalla entre las fuerzas de Valion y Zamordax que tuvo lugar más allá de las negras cumbres de oriente, en la Tundra de los Ancestros. Pero las consecuencias de aquel fragor de armas y almas aún perduran en la tierra maldita y, su legado, amenaza con inundar los páramos helados de una nueva oscuridad.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/c4-la-cupula-de-huesos-de-ixambel.md'),
  ('LM252C5', 'C5', 'C', 5, 'La Prueba de Lenzen', 'Jose Mariano Saez', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '44', 'grapado color', 'A4 b/n', 9.00, '2024-05-17', '9780201379626', 'LM252C5', 'ALMEC5', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Tiene prefijo ISBN 978/979, pero el checksum EAN-13 no es válido", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM252C5", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM252C5", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
