  ('LM255CS', 'CS', 'CS', null, 'Corona de sal', 'Tania Herrero', 'Suplemento', (select id from public.categories where slug = 'otros'), '120', 'rústica color con solapas', 'color A5', 25.00, '2024-07-05', 'LM255CS', 'LM255CS', null, '{"estado_codigo": "derivado_clave_sombra", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM255CS", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM255CS", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
  ('LM227CT1', 'CT1', 'CT', 1, 'La Lágrima de Zurâh', 'Antonio Ramón Berbell Gonell', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '32', 'grapado color', 'A4 b/n', 6.00, '2020-11-09', '8580200071625', 'LM227CT1', 'ALMECT1', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "EAN-13 válido por checksum, pero no tiene prefijo ISBN 978/979", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM227CT1", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 3, 4, 4, 5, 3, array['Campaña', 'Dungeon', 'Exploración', 'Urbano']::text[], 'Hace muchas lunas los Leones del Desierto secuestraron al decimotercer hijo del emir. El legendario gobernante de Palmira ha enviado a sus mejores hombres para recuperar a su hijo, comandados por el valeroso general Usamah Al-Zafir. Juntos deberán seguir la pista de los secuestradores, recorriendo el mar de huesos de Eretria, arrostrando peligros ignotos mientras descubren ruinas de otrora sepultadas en las arenas del tiempo.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/ct1-la-lagrima-de-zurah.md'),
  ('LM276CT2', 'CT2', 'CT', 2, 'El Sello del Profeta', 'Antonio Ramón Berbell Gonell', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '44', 'grapado color', 'A4 b/n', 22.00, '2025-12-19', '1680201369619', 'LM276CT2', 'ALMECT2', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "EAN-13 válido por checksum, pero no tiene prefijo ISBN 978/979", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM276CT2", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM276CT2", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
  ('LM275D1', 'D1', 'D', 1, 'Dioses y Clérigos', 'Juanmi Ferez (y otros autores)', 'Suplemento', (select id from public.categories where slug = 'suplementos'), '48', 'grapado color', 'A4 b/n', 15.00, '2025-12-19', '9770201079600', 'LM275D1', 'ALMED1', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "EAN-13 válido por checksum, pero no tiene prefijo ISBN 978/979", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM275D1", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM275D1", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
  ('LM211E1', 'E1', 'E', 1, 'El Legado Perdido (Crónicas Olvidadas)', 'Diego Marqués Vega (Códice)', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '32 + mapa A3', 'grapado color', 'b/n A4', 8.00, '2018-05-25', '.', 'LM211E1', 'ALMEE1', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM211E1", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM211E1", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
  ('LM226ES1', 'ES1', 'ES', 1, 'La Furia de Rastilon', 'Pedro Gil', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '24 + 1 mapa A3 color', 'grapado color', 'A4 b/n', 7.00, '2020-11-09', '.', 'LM226ES1', 'ALMEES1', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM226ES1", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM226ES1", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 15, 17, 4, 6, 2, array['Ciencia Fantasía', 'Dragón', 'Dungeon', 'Exploración', 'Exterior', 'Sandbox']::text[], 'Un gran peligro se abate sobre la Marca del Este, tal vez la amenaza más grave que jamás pudiéramos imaginar, llegada de allende las estrellas. El Imperio Rastilon ha puesto sus ojos en Valion y sólo los más grandes héroes que jamás hayan existido podrán conjurar este desafío. Es la hora de la verdad.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/la-furia-de-rastilon.md'),
  ('LM200GZ', 'G0', 'G', 0, 'Gazetteer de la Marca del Este', 'Varios', 'Suplemento', (select id from public.categories where slug = 'ambientacion'), '180 + pantalla + 15 mapas', 'caja', 'b/n A4 (planos y exterior pantalla color)', 40.00, '2018-03-23', 'LM200GZ', 'LM200GZ', 'ALMEG0', '{"estado_codigo": "especial_gazetteer", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM200GZ", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
  ('LM213G1', 'G1', 'G', 1, 'Un Paseo por el Campo', 'Pedro Gil', 'Suplemento', (select id from public.categories where slug = 'ambientacion'), '36 + mapa color A3', 'rústica-color en tríptico', 'b/n A4', 10.00, '2018-12-17', '.', 'LM213G1', 'ALMEG1', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM213G1", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 36, 4, 6, null, array['Gazetteer']::text[], 'Cerca del misterioso Valle Sagrado, en los páramos y parajes orientales de la Marca del Este, entre oteros y riscales se enclava el viejo pueblo de Nidaros.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/G1-un-paseo-por-el-campo.md'),
  ('LM219G2', 'G2', 'G', 2, 'Alameda', 'Santi Pastor', 'Suplemento', (select id from public.categories where slug = 'ambientacion'), '24 + mapa', 'rústica-color', 'b/n A4 + mapa A3 color', 7.00, '2019-10-25', '.', 'LM219G2', 'ALMEG2', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM219G2", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 36, 4, 6, null, array['Gazetteer']::text[], 'El viejo pueblo de Alameda se asienta en las tierras orientales fronterizas de la Marca del Este, en la indómita región a caballo entre el belicoso reino de Ungoloz y los baldíos páramos desérticos de Visirtan. Y es aquí donde nuestros héroes continuarán sus aventuras, explorando una comarca antigua preñada de ruinas fabulosas y misterios ocultos por las arenas del tiempo.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/G2-alameda.md'),
  ('LM228G3', 'G3', 'G', 3, 'Las Frondas de los Medianos', 'Carlos de la Cruz', 'Suplemento', (select id from public.categories where slug = 'ambientacion'), '20 + 1 mapa A3 color', 'grapado color', 'A4 b/n', 6.00, '2020-11-09', '9788881388622', 'LM228G3', 'ALMEG3', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM228G3", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 36, 4, 6, null, array['Gazetteer']::text[], 'Este libro es una descripción de la región conocida como las Frondas de los Medianos, la única nación habitada mayoritariamente por la raza de los medianos en el mundo de Valion.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/G3-fronda-de-los-medianos.md'),
