  ('codex:H1', 'H1', 'H', 1, 'La Aldea Asolada por la Muerte', null, 'Aventura histórica', (select id from public.categories where slug = 'historicas'), null, null, null, null, null, null, null, 'ALMEH1', '{"estado_codigo": "confirmado_codex_sin_sombra_actual", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin dato en el catálogo actual de Sombra", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 3, 3, 5, 2, array['Aldea', 'Exterior', 'Investigación']::text[], 'En una apacible aldea, la Muerte camina entre los vivos. Solo un grupo de aguerridos aventureros será capaz de enfrentarse a los muertos cuando éstos decidan alzarse contra quienes aún siguen en pie.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/h1-la-aldea-asolada-por-la-muerte.md'),
  ('codex:H2', 'H2', 'H', 2, 'El Último Caballero de la Orden Escarlata', null, 'Aventura histórica', (select id from public.categories where slug = 'historicas'), null, null, null, null, null, null, null, 'ALMEH2', '{"estado_codigo": "confirmado_codex_sin_sombra_actual", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin dato en el catálogo actual de Sombra", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 2, 4, 3, 5, 2, array['Dungeon']::text[], 'Una reliquia maldita está haciendo que criaturas malignas deambulen por nuestro mundo, trayendo consigo el caos y la muerte que su señor, Penumbra, les ha ordenado. Un caballero, el último de su orden, ha jurado acabar con ese mal y para ello, ayudado por los aventureros, se adentrará en la tumba que debía custodiar la reliquia.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/h2-el-ultimo-caballero-de-la-orden-escarlata.md'),
  ('codex:H3', 'H3', 'H', 3, 'Nuestros Hermanos Caídos en Batalla', null, 'Aventura histórica', (select id from public.categories where slug = 'historicas'), null, null, null, null, null, null, null, 'ALMEH3', '{"estado_codigo": "confirmado_codex_sin_sombra_actual", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin dato en el catálogo actual de Sombra", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 3, 5, 3, 5, 2, array['Dungeon']::text[], 'Cuando un ejército de muertos vivientes se levanta para acabar con toda vida en la Marca, solo un secreto guardado por la Reina Vigdis II podrá evitar el temible final que nos aguarda.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/h3-nuestros-hermanos-caidos-en-batalla.md'),
  ('codex:H4', 'H4', 'H', 4, 'La Espada en la Roca', null, 'Aventura histórica', (select id from public.categories where slug = 'historicas'), null, null, null, null, null, null, null, 'ALMEH4', '{"estado_codigo": "confirmado_codex_sin_sombra_actual", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin dato en el catálogo actual de Sombra", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 5, 7, 3, 5, 2, array['Dungeon']::text[], 'Cuenta la leyenda que aquel que sea capaz de sacar la espada de la roca en la que se encuentra clavada, tendrá el poder absoluto a su alcance. ¿Pero qué sucedería si la leyenda estuviera mal desde sus orígenes? ¿Y si el poder absoluto es en realidad una simple quimera?', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/h4-la-espada-en-la-roca.md'),
  ('LM246HO1', 'HO1', 'HO', 1, 'Lo que el Ojo no ve', 'vv.aa.', 'Suplemento', (select id from public.categories where slug = 'otros'), '62', 'rústica color', 'A4 b/n', 12.00, '2023-05-19', '9782253058151', 'LM246HO1', 'ALMEHO1', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM246HO1", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 2, 3, 4, 6, 4, array['Exploración', 'Investigación', 'Urbano']::text[], 'Se presenta aquí la reedición de la aventura publicada por Holocubierta, en un nuevo formato más acorde a la línea de Clásicos, pero que conserva la esencia que el autor transmitió en la publicación original.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/ho1-lo-que-el-ojo-no-ve.md'),
