  ('LM245MN2', 'MN2', 'MN', 2, 'La balada del efímero paladín', 'Manu Saez', 'Suplemento', (select id from public.categories where slug = 'aventuras'), null, 'grapado color', 'A4 b/n', 8.00, '2023-03-17', '9780201370058', 'LM245MN2', 'ALMEMN2', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM245MN2", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM245MN2", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 1, 2, 4, 6, 2, array['Dungeon', 'Exploración', 'Marjalnegro']::text[], 'Adéntrate en Marjalnegro, y disfruta con tus aventureros de este entorno desconocido, lleno de misterios y aventuras. Este es el primer módulo ambientado en esta tierra de oportunidades para los más bravos y aguerridos', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/mn2-la-balada-del-efimero-paladin.md'),
  ('LM263MN3', 'MN3', 'MN', 3, 'Guía Marjalnegro + Hasta que la Muerte os Separe', 'Fali Ruíz-Davila', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '12+24', 'grapado color', 'A4 b/n', 18.00, '2025-05-09', '9780209632622', 'LM263MN3', 'ALMEMN3', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM263MN3", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM263MN3", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 6, 8, 3, 5, 4, array['Investigación', 'Marjalnegro']::text[], 'Marjalnegro es un terreno poco conocido, pero en absoluto carente de emociones, peligros y secretos. Una tierra cuyo delicado equilibrio podría irse al traste, por culpa de una simple muerte accidental o a través de una elaborada traición.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/mn3-hasta-que-la-muerte-os-separe.md'),
