  ('LM295SP2', 'SP2', 'SP', 2, 'El Laberinto de las Mil Puertas', 'vv.aa.', 'Suplemento', (select id from public.categories where slug = 'suplementos'), '20', 'grapado color', 'A4 b/n', 10.00, '2026-05-29', '9785432277626', 'LM295SP2', 'ALMESP2', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM295SP2", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM295SP2", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', null, null, null, null, null, '{}'::text[], null, null),
  ('LM221TN1', 'TN1', 'TN', 1, 'Pacto de Cenizas', 'Diego Marqués Vega', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '28', 'rústica-color', 'b/n A4', 7.00, '2019-10-25', '.', 'LM221TN1', 'ALMETN1', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM221TN1", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM221TN1", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 2, 4, 3, 4, 2, array['Campaña', 'El Trono de Niebla', 'Fortaleza', 'Investigación']::text[], 'Un oscuro pacto sellado en el corazón del reino, unos personajes marcados por sus pecados, un terror llegado desde las profundidades del pasado, una conspiración a punto de ser revelada y un templo en tinieblas.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/tn1-pacto-de-cenizas.md'),
  ('LM222TN2', 'TN2', 'TN', 2, 'El Feudo en Llamas', 'Diego Marqués Vega', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '32', 'rústica-color', 'b/n A4', 7.00, '2019-10-25', '.', 'LM222TN2', 'ALMETN2', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM222TN2", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM222TN2", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 3, 5, 4, 5, 2, array['Campaña', 'El Trono de Niebla', 'Investigación', 'Urbano']::text[], 'Un ejército perdido en su hora más aciaga, una ciudad sometida a asedio por una fuerza implacable, unos personajes a punto de perder sus hogares, dos asesinatos a punto de ser perpetrados y un castillo envuelto en llamas.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/tn2-el-feudo-en-llamas.md'),
  ('LM229TN3', 'TN3', 'TN', 3, 'El Corazón de la Oscuridad', 'Diego Marqués Vega', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '182 + carpeta con 15 mapas A3 + cuad. A5 20 pág.', 'cartoné color', 'A4 b/n', 40.00, '2020-11-09', '.', 'LM229TN3', 'ALMETN3', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Sin ISBN según Sombra", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM229TN3", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM229TN3", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 4, 5, 4, 5, 15, array['Campaña', 'El Trono de Niebla', 'Megadungeon']::text[], 'En las entrañas de Marvalar, oculta durante siglos por el paso del tiempo y la ignorancia, se halla una antiquísima y gigantesca mazmorra, llena de tesoros, hechizos y criaturas sin par. Nuestros personajes se verán involucrados en la exploración de este subterráneo a petición de la propia corona de Marvalar, alertada de la presencia del lugar por un súbito ataque sorpresa sobre la capital. En su recorrido por sus espantosas salas, descubrirán verdades terribles que nunca pensaron que llegarían a vislumbrar, no solo sobre el mundo al que tanto aman, sino también sobre si mismos.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/tn3-el-corazon-de-la-oscuridad.md'),
  ('LM206V1', 'V1', 'V', 1, 'El Castillo Prohibido de la Reina de Sangre', 'José Manuel Palacios', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '32', 'encarte tríptico-grapado-color', 'b/n - A4', 8.00, '2017-01-25', 'LM206V1', 'LM206V1', 'ALMEV1', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM206V1", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM206V1", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 6, 10, 5, 6, null, array['Exploración', 'Fortaleza', 'Sandbox', 'Urbano', 'Vermigor']::text[], 'El castillo de Varania tiene una nueva señora que ha traído el caos y el terror al Valle de Galas y sus habitantes. Nunca antes una tierra había estado tan maldita y nunca antes un grupo de héroes había sido tan necesario. ¿Aceptarán los personajes el desafío? El Castillo Prohibido de La Reina de Sangre os espera.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/v1-el-castillo-prohibido-de-la-reina-de-sangre.md'),
  ('LM232V2', 'V2', 'V', 2, 'No profanarás el Sueño de los Muertos', 'José Carlos de Diego', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '44', 'grapado color', 'A4 b/n', 9.00, '2021-06-11', '9700201000922', 'LM232V2', 'ALMEV2', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "EAN-13 válido por checksum, pero no tiene prefijo ISBN 978/979", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM232V2", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM232V2", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 6, 8, 3, 5, null, array['Investigación', 'Reglamento', 'Urbano', 'Vermigor']::text[], 'El Circo de los Magníficos ha llegado a la populosa ciudad de Morowen, la capital de Mourntall, durante la semana de su carnaval, el mayor espectáculo popular de Vermigor. No tardarán en producirse toda suerte de extraños y macabros sucesos en las calles de la abarrotada urbe, mientras nuestros aventureros tratan de desentrañar los misterios tras la siniestra troupe circense. Algo terrible esta a punto de suceder...', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/no-profanaras-el-sueno-de-los-muertos.md'),
  ('LM253V3', 'V3', 'V', 3, 'El Ojo de Sa''nna', 'Joaquín Blanes Garrido', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '24', 'grapado color', 'A4 b/n', 7.50, '2024-05-31', '9780201300093', 'LM253V3', 'ALMEV3', '{"estado_codigo": "confirmado_codex", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Formato ISBN-13/EAN-13 válido por checksum; no implica verificación registral", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM253V3", "fuente_codigo": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 3, 3, 4, 6, 2, array['Investigación', 'Templo', 'Terror', 'Vermigor']::text[], 'El pueblo de Raimus Caimas en Vermigor lleva años padeciendo los ataques de una criatura desconocida cada mes durante la luna llena.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/V3-el-ojo-de-sanna.md'),
  ('LM205X1', 'X1', 'X', 1, 'En busca de la Ciudad Perdida de Garan', 'Carlos de la Cruz', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '44', 'encarte-grapado-color', 'b/n - A4', 7.00, '2017-01-25', 'LM205X1', 'LM205X1', 'ALMEX1', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM205X1", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM205X1", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 5, 8, 3, 5, 3, array['Bosque', 'Exploración', 'Exterior', 'Sandbox', 'Selva']::text[], 'Un gran misterio aguarda en lo más profundo de las junglas de Cirinea, la legendaria ciudad perdida de Garan.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/x1-la-ciudad-perdida-de-garan.md'),
  ('LM210X2', 'X2', 'X', 2, 'El Arca de los Mil Inviernos', 'Jordi Morera', 'Suplemento', (select id from public.categories where slug = 'aventuras'), '56', 'grapado + mapa', 'b/n A4', 9.00, '2018-03-23', 'LM210X2', 'LM210X2', 'ALMEX2', '{"estado_codigo": "derivado_clave_sombra", "estado_sku_tesoros": "esperado_por_patron", "nota_isbn": "Valor literal publicado por Sombra; no tiene formato ISBN/EAN-13", "fuente_sombra": "https://dbsombra.com/index.asp?cod=LM210X2", "fuente_codigo": "https://dbsombra.com/index.asp?cod=LM210X2", "fuente_codex": "https://github.com/diacritica/codexlmde/tree/master/codex/content/es/posts"}'::jsonb, 'approved', 'csv', 6, 10, 4, 7, 5, array['Exploración', 'Exterior', 'Isla', 'Sandbox']::text[], 'El más terrible de los peligros aguarda en el interior de un legendario artefacto perdido en los confines de la Isla Boreal: el Arca de los Mil Inviernos.', 'https://github.com/diacritica/codexlmde/blob/master/codex/content/es/posts/x2-el-arca-de-los-mil-inviernos.md'),
